import type { BlogArticle } from "../../../blog";
const article: BlogArticle = {"slug": "ai-character-generator", "oldSlugs": [], "column": "guide", "category": "guide", "title": "Rosto muda a cada cena? Crie o mesmo personagem com IA", "seoTitle": "Gerador de personagens com IA: mesmo rosto | DramaCanvas", "summary": "Para usar um gerador de personagens com IA mantendo o mesmo rosto em cada cena, conecte até 30 imagens de referência em um nó de vídeo no canvas infinito. Aprenda a criar uma folha de personagem com 4 ângulos, travar o figurino no prompt e conectar cartões a nós de vídeo e áudio.", "author": "", "date": "2026-11-04", "modifiedDate": "2026-11-04", "updated": "2026-11-04", "status": "published", "seoApproved": true, "sourceLocale": "pt-BR", "publishedLocales": ["pt-BR"], "intro": ["O fluxo de trabalho com um **gerador de personagens com IA** resolve o maior obstáculo do audiovisual generativo: evitar que o rosto de um personagem mude de aparência entre uma cena e outra. Quando você orienta um modelo de vídeo apenas com comandos de texto, o sistema gera uma pessoa totalmente nova a cada tentativa. Criar produções narrativas consistentes exige travar essa identidade visual primeiro em imagens estáticas e depois injetar essas referências visuais diretamente na geração de vídeo.", "Em um canvas infinito, você faz isso criando uma folha-mestre de personagem com múltiplos ângulos, salvando esse material no seu projeto e conectando essas imagens de referência diretamente aos nós de vídeo e áudio seguintes. Ao combinar modelos de imagem como o [[link:gpt-image-guide-2026|GPT Image 2]] ou o [[link:nano-banana-pro|Nano Banana Pro]] com geradores de vídeo multirreferência como o [[link:seedance-2-5|Seedance 2.5]], você mantém os mesmos traços faciais, estrutura corporal e figurino ao longo de uma série inteira.", "A leitura deste guia leva cerca de 14 minutos. Ao final, você terá uma estrutura de prompts pronta para copiar, uma estratégia para escolher o modelo ideal e um passo a passo nó por nó para renderizar o mesmo personagem em cada cena no [DramaCanvas](https://dramacanva.com)."], "takeaways": ["**Folhas-mestre fixam a identidade visual**: Criar uma folha de referência com 4 ângulos — frente, três quartos, perfil e corpo inteiro — estabelece a estrutura facial e as proporções corporais antes de renderizar qualquer movimento.", "**A capacidade de referências dita a consistência**: O [[link:seedance-2-5|Seedance 2.5]] da ByteDance aceita até 30 imagens de referência simultâneas, oferecendo a maior retenção visual entre os modelos disponíveis no DramaCanvas.", "**Instruções de cena se sobrepõem a folhas estáticas**: Um cartão de referência de identidade fixa os traços faciais e a estrutura óssea, enquanto o prompt da cena comanda ações dinâmicas, expressões e efeitos causados pelo ambiente.", "**Conexões visuais custam zero créditos**: Adicionar cartões de imagem, recortar ângulos e conectar linhas de referência no canvas infinito não consome seu saldo até que você envie uma tarefa de vídeo para renderização."], "questions": [{"id": "question-1", "title": "Como um gerador de personagens com IA mantém o mesmo personagem em cada cena?"}, {"id": "question-2", "title": "Como criar e estruturar o prompt de uma folha-mestre de personagem?"}, {"id": "question-3", "title": "Qual modelo de vídeo oferece a melhor consistência de personagens no DramaCanvas?"}, {"id": "question-4", "title": "Como conectar referências de personagens aos nós de vídeo e áudio no canvas?"}, {"id": "question-5", "title": "O que causa a perda de consistência em vídeos com IA e como resolver isso?"}], "sections": [{"id": "question-1", "title": "Como um gerador de personagens com IA mantém o mesmo personagem em cada cena?", "paragraphs": ["Um gerador de personagens com IA preserva a identidade condicionando a geração do vídeo a um conjunto de 4 a 30 imagens de referência aprovadas, em vez de depender exclusivamente de comandos de texto. Quando você fornece apenas texto, o modelo inventa novos traços faciais, estilos de cabelo e estruturas ósseas a cada clique em gerar. O envio de imagens de referência direciona o modelo para reproduzir exatamente o mesmo rosto, as mesmas proporções e o mesmo figurino em cada corte.", "Como documentado no [curso de referência de personagens da ScreenWeaver](https://www.screenweaver.ai/academy/courses/ai-filmmaking-course/consistent-ai-characters-reference-sheets), o público percebe inconsistências faciais instantaneamente, o que quebra a imersão narrativa. Para superar isso, fluxos de trabalho profissionais separam a identidade das variáveis da cena. Suas imagens de referência definem a anatomia facial e a silhueta das roupas, enquanto seu prompt de texto dita o movimento de câmera, a interpretação emocional e a iluminação da cena.", "No DramaCanvas, essa separação é física. Você escreve o roteiro em um nó de Texto, renderiza imagens estáticas de referência em um nó de Imagem e direciona essas imagens por conexões visuais até um nó de Vídeo. O modelo receptor interpreta os pixels conectados como o visual definitivo do seu ator, reduzindo drasticamente variações faciais entre os cortes."], "blocks": [{"type": "paragraph", "index": 0}, {"type": "paragraph", "index": 1}, {"type": "paragraph", "index": 2}]}, {"id": "question-2", "title": "Como criar e estruturar o prompt de uma folha-mestre de personagem?", "paragraphs": ["Uma folha-mestre de personagem exige 4 ângulos fundamentais — retrato frontal, ângulo em três quartos, perfil lateral e silhueta de corpo inteiro — renderizados contra um fundo de estúdio cinza uniforme. Desenvolver essa folha inicial em um modelo de imagem fornece aos modelos de vídeo posteriores todas as informações espaciais sobre o maxilar, a linha do cabelo e a estrutura corporal do personagem.", "De acordo com o [fluxo de consistência de personagens da Astorie](https://astorie.ai/how-to/keep-same-character-across-ai-videos), gerar quatro ângulos distintos em uma única folha-mestre evita as variações faciais que surgem ao gerar retratos de referência separadamente. Modelos de imagem como o [[link:gpt-image-guide-2026|GPT Image 2]] e o [[link:nano-banana-pro|Nano Banana Pro]] são excelentes para produzir folhas de contato limpas em múltiplos painéis quando recebem restrições de layout bem definidas.", "**Passo 1: Escreva o parágrafo de identidade e o bloco do personagem**", "Comece definindo a base visual do personagem em um nó de Texto no canvas. Descreva idade, traços étnicos, formato do rosto, textura do cabelo, formato dos olhos e exatamente dois elementos visuais marcantes, como um cardigã de tricô amarelo-mostarda ou uma cicatriz sutil sobre a sobrancelha esquerda. Pesquisas do [guia de folhas de referência da SuperDuperAI](https://superduperai.co/library/character-consistency-reference-sheet/) comprovam que duas marcas visuais evidentes fixam a identidade com muito mais eficiência do que dez adjetivos genéricos.", "Nunca altere esse parágrafo de identidade entre as cenas. Cole exatamente o mesmo bloco descritivo em todos os prompts posteriores para reforçar as referências visuais.", "**Passo 2: Gere a folha multiângulo em um nó de Imagem**", "Clique em **Add node** na barra de ferramentas inferior do canvas, selecione **Image** e defina a proporção de tela como 16:9 nas configurações de imagem. Cole seu bloco de identidade combinado com instruções explícitas de layout em múltiplos painéis na caixa de prompt.", "Clique em **Generate** para renderizar a folha. Após a conclusão, mude o canvas para o modo Professional, passe o cursor sobre a barra do cartão de Imagem e selecione **Grid split** para recortar a folha de contato em cartões individuais independentes. Isso gera cartões separados para os ângulos frontal, de perfil e três quartos sem gastar gerações adicionais."], "blocks": [{"type": "paragraph", "index": 0}, {"type": "paragraph", "index": 1}, {"type": "paragraph", "index": 2}, {"type": "paragraph", "index": 3}, {"type": "paragraph", "index": 4}, {"type": "paragraph", "index": 5}, {"type": "paragraph", "index": 6}, {"type": "code", "index": 0}, {"type": "paragraph", "index": 7}, {"type": "figure", "index": 0}], "code": [{"label": "Master character sheet prompt", "content": "Character reference sheet of Marcus: a 28-year-old man, sharp jawline, short textured dark fade haircut, amber-brown eyes, and a small faint scar over his left eyebrow. Athletic build, wearing a clean olive utility jacket over a charcoal crewneck t-shirt and dark denim. Four distinct views arranged horizontally: full-body front-facing standing pose, head-and-shoulders three-quarter portrait, sharp side profile, and full-body rear view showing hairstyle and jacket back. Neutral facial expression, even flat studio lighting, solid neutral light grey background, clean concept art layout. No text, no overlapping figures, perfectly consistent facial structure and wardrobe across all four panels.", "language": "text"}], "figures": [{"src": "/blog-media/figures/ai-character-generator/fig-01-sheet.jpg", "webp": "/blog-media/figures/ai-character-generator/fig-01-sheet.webp", "width": 1920, "height": 1412, "alt": "Folha mestre de quatro ângulos do Marcus com prompt antes do Grid split", "caption": "Folha mestre de quatro ângulos do Marcus com prompt antes do Grid split"}]}, {"id": "question-3", "title": "Qual modelo de vídeo oferece a melhor consistência de personagens no DramaCanvas?", "paragraphs": ["O Seedance 2.5 da ByteDance aceita até 30 imagens de referência simultâneas, sendo o modelo de vídeo mais flexível para retenção de personagens no DramaCanvas. Ao escolher um gerador de vídeo, sua métrica principal deve ser a capacidade de referências: modelos que aceitam múltiplas imagens de entrada preservam os traços faciais durante giros de cabeça e rotações de câmera complexas com muito mais fidelidade do que modelos de quadro único.", "Desde que a OpenAI encerrou os modelos Sora 2 e a Videos API em 24 de setembro de 2026, os modelos multirreferência se tornaram a forma principal de manter personagens consistentes. Você pode conferir os comparativos completos da plataforma no nosso guia de [[link:sora-shutdown-alternatives|alternativas ao encerramento do Sora]] e no nosso ranking dos [[link:best-ai-video-generator-2026|melhores geradores de vídeo com IA em 2026]].", "A tabela a seguir detalha os modelos de vídeo disponíveis no DramaCanvas, seus custos em créditos e seus limites de entrada para consistência de personagens:", "| Modelo (criador) | Resolução e créditos por segundo (créditos/s) | Duração (s) | Proporções de tela | Máximo de imagens de referência | Limitações e Regras de Entrada | |---|---|---|---|---|---| | Seedance 2.5 (ByteDance) | 480p: 14 · 720p: 30 · 1080p: 74 | 4–30 s | 6 proporções | Até 30 imagens | Até 10 clipes de áudio de referência; rejeita vídeo de referência no DramaCanvas | | Seedance 2.0 (ByteDance) | 480p: 10 · 720p: 20 · 1080p: 50 | 4–15 s (720p até 30 s) | 6 proporções | Até 9 imagens | Suporta 3 vídeos de referência e 3 clipes de áudio de referência | | Seedance 2.0 Fast | 480p: 8 · 720p: 17 | 4–15 s | 6 proporções | Até 9 imagens | Menor latência; suporta 3 vídeos de referência e 3 clipes de áudio | | Seedance 2.0 Mini | 480p: 7 · 720p: 10 | 4–15 s | 6 proporções | Até 9 imagens | Econômico; não aceita entrada de vídeo de referência | | Wan 3.0 (Alibaba) | 480p: 6 · 720p: 12 · 1080p: 24 | 2–30 s | 6 proporções | Até 10 imagens | Também aceita 5 vídeos de referência e 5 clipes de áudio | | Kling 4 (Kuaishou) | 720p: 7 · 1080p: 12 | 3–30 s | 16:9 / 9:16 / 1:1 / 21:9 | Até 10 imagens | Menor custo em 720p nesta lista; apenas imagens, sem referências de vídeo ou áudio | | Kling 3.0 (Kuaishou) | 720p: 8 (12 com áudio) · 1080p: 16 · 4K: 40 | 3–15 s | 16:9 / 9:16 / 1:1 | 2 imagens no máximo | Opera estritamente como quadro inicial e quadro final; sem painel geral de referências | | MiniMax H3 (Hailuo) | 480p: 5 · 768p: 8 · 1080p: 13 | 4–30 s (1080p até 15 s) | 6 proporções | 1 imagem no máximo | Opera estritamente como quadro inicial; rejeita conexões de múltiplas imagens de referência | | Grok Imagine Video 1.5 (xAI) | 480p: 6 · 720p: 10 | 4–15 s | 6 proporções | Até 7 imagens | Resolução máxima de 720p; limite de 15 segundos |", "Créditos verificados no DramaCanvas em 04/11/2026.", "O DramaCanvas calcula a cobrança por segundo de vídeo gerado. No plano Standard (US$ 29,90 por mês para 1.100 créditos), 1 crédito equivale a aproximadamente US$ 0,027. Gerações que falham são reembolsadas automaticamente no saldo da sua conta.", "Para avaliar os custos reais de produção:", "Para manter a consistência de personagens em produções narrativas, escolha o Seedance 2.5 quando precisar fornecer referências visuais abrangentes de figurino, rosto e cenário em uma única geração. Caso trabalhe com orçamentos mais enxutos, o Kling 4 e o Wan 3.0 entregam alta fidelidade visual com até 10 imagens de referência consumindo menos créditos."], "blocks": [{"type": "paragraph", "index": 0}, {"type": "paragraph", "index": 1}, {"type": "paragraph", "index": 2}, {"type": "table", "index": 3}, {"type": "paragraph", "index": 4}, {"type": "paragraph", "index": 5}, {"type": "paragraph", "index": 6}, {"type": "list", "items": ["O [[link:seedance-2-5|Seedance 2.5]] em 720p para uma cena de 10 segundos consome 300 créditos (US$ 8,10).", "O [[link:seedance-2|Seedance 2.0]] em 720p para uma cena de 10 segundos consome 200 créditos (US$ 5,40).", "O [[link:wan-3-guide|Wan 3.0]] em 720p para uma cena de 10 segundos consome 120 créditos (US$ 3,24).", "O [[link:kling-ai-guide-2026|Kling 4]] em 720p para uma cena de 10 segundos consome 70 créditos (US$ 1,89)."]}, {"type": "paragraph", "index": 7}]}, {"id": "question-4", "title": "Como conectar referências de personagens aos nós de vídeo e áudio no canvas?", "paragraphs": ["No DramaCanvas, conectar referências de consistência de personagens significa arrastar uma linha da porta de saída direita de um nó de Imagem até a porta de entrada esquerda de um cartão de Vídeo ou Áudio. A estrutura visual do canvas substitui engenharia de prompts complexa por roteamento espacial direto, permitindo que uma única folha-mestre alimente dezenas de cartões de cena simultaneamente.", "Como destacado na [documentação de prompts de personagens da Fawna](https://fawna.ai/docs/prompting/character/), modelos de vídeo respondem muito melhor a referências visuais associadas a descrições textuais precisas. No DramaCanvas, as conexões conduzem os dados de mídia da esquerda para a direita.", "**Passo 3: Salve os retratos recortados como cartões de personagem nos recursos do projeto**", "Na barra superior, certifique-se de que seu canvas esteja vinculado a um projeto em \"My canvases\". Agrupar os quadros de episódios dentro de um projeto permite acessar o painel \"Project assets\".", "Selecione os cartões aprovados de retrato frontal e de perfil gerados na etapa Grid split. Adicione-os aos recursos do projeto como um cartão de personagem nomeado (por exemplo, \"Marcus\"). Salvar os ativos do personagem no nível do projeto permite que múltiplos quadros de episódios compartilhem os mesmos cartões de referência sem precisar reenviar os arquivos repetidamente.", "**Passo 4: Conecte as imagens de referência e defina o quadro inicial no nó de Vídeo**", "Clique em **Add node** na barra de ferramentas inferior, selecione **Video** e posicione o nó à direita dos seus cartões de imagem. Escolha o modelo desejado, como o [[link:kling-ai-guide-2026|Kling 4]] ou o [[link:seedance-2-5|Seedance 2.5]].", "Clique e segure o ponto de conexão circular na borda direita do seu cartão de personagem, arraste a linha pelo painel e solte-a sobre a porta de entrada esquerda do nó de Vídeo. Repita o processo com os cartões de três quartos e de corpo inteiro. O DramaCanvas elimina conexões duplicadas automaticamente: conectar a mesma imagem de origem mais de uma vez consome apenas um slot de referência.", "Abaixo da caixa de prompt, expanda a seção **Parameters**. No menu suspenso **Start frame**, selecione a imagem-chave que definirá a composição de abertura da cena. Se a sua cena exige apenas semelhança geral de identidade em vez de um ponto de partida estático, mantenha o Start frame configurado como \"Not specified\"; dessa forma, o modelo usará os cartões conectados apenas como âncoras de identidade.", "**Passo 5: Escreva o prompt da cena vinculando a referência com @Image**", "Escreva o prompt da cena usando uma fórmula estruturada em cinco partes: Cenário + Aparência do Personagem + Ação Principal + Diálogo + Trajetória da Câmera. Faça referência explícita à imagem conectada usando a marcação `@Image`.", "Verifique o custo em créditos exibido ao lado da seta de geração e clique em **Generate**. A tarefa avança pelos status Queued e Generating, renderizando o clipe de vídeo em MP4 diretamente no cartão.", "**Passo 6: Conecte um cartão de personagem com voz vinculada a um nó de Áudio**", "A consistência visual precisa caminhar junto com a continuidade vocal. Clique em **Add node** no menu inferior e selecione **Audio** (com dimensões de 340×120).", "Nas configurações, a opção Voice padrão é alloy, ao lado de perfis vocais alternativos; o formato padrão é mp3, e a velocidade de fala alterna entre 0.75x e 1.5x, com um controle deslizante que varia de 0.25x a 4.0x. No campo \"Voice instructions\", descreva a entonação do seu personagem em linguagem natural (por exemplo: \"Uma voz masculina cautelosa e grave, falando em um ritmo calmo e medido\").", "Conecte o cartão do seu personagem à porta de entrada esquerda do nó de Áudio. Preste atenção à regra de conexão estrita: nós de Áudio aceitam apenas prompts de texto ou exatamente 1 cartão de personagem com voz vinculada. O nó rejeita clipes de vídeo, imagens estáticas comuns ou arquivos de áudio secundários."], "blocks": [{"type": "paragraph", "index": 0}, {"type": "paragraph", "index": 1}, {"type": "paragraph", "index": 2}, {"type": "paragraph", "index": 3}, {"type": "paragraph", "index": 4}, {"type": "paragraph", "index": 5}, {"type": "paragraph", "index": 6}, {"type": "paragraph", "index": 7}, {"type": "figure", "index": 0}, {"type": "paragraph", "index": 8}, {"type": "paragraph", "index": 9}, {"type": "paragraph", "index": 10}, {"type": "code", "index": 0}, {"type": "paragraph", "index": 11}, {"type": "figure", "index": 1}, {"type": "paragraph", "index": 12}, {"type": "paragraph", "index": 13}, {"type": "paragraph", "index": 14}, {"type": "paragraph", "index": 15}], "figures": [{"src": "/blog-media/figures/ai-character-generator/fig-02-references.jpg", "webp": "/blog-media/figures/ai-character-generator/fig-02-references.webp", "width": 1920, "height": 2368, "alt": "Conexão do cartão de personagem à porta de entrada do nó de Vídeo", "caption": "Conexão do cartão de personagem à porta de entrada do nó de Vídeo"}, {"src": "/blog-media/figures/ai-character-generator/fig-03-settings.jpg", "webp": "/blog-media/figures/ai-character-generator/fig-03-settings.webp", "width": 1920, "height": 2978, "alt": "Seedance 2.5 em 720P, 9:16 e 10s exibindo custo de 300 créditos", "caption": "Seedance 2.5 em 720P, 9:16 e 10s exibindo custo de 300 créditos"}], "code": [{"label": "Scene shot prompt with reference binding", "content": "Setting: Dimly lit subway platform at midnight, wet concrete tiles reflecting cool overhead fluorescent tubes.\nCharacter: Marcus, matching @Image1 for facial features and haircut, wearing his olive utility jacket and charcoal crewneck t-shirt.\nAction: Marcus paces along the yellow safety line, glances down at his wrist watch, exhales nervously, and turns toward the empty tunnel tracks.\nCamera: 9:16 vertical medium shot, slight low angle tracking backward smoothly as Marcus walks forward, 50mm lens perspective, subtle atmospheric mist.", "language": "text"}]}, {"id": "question-5", "title": "O que causa a perda de consistência em vídeos com IA e como resolver isso?", "paragraphs": ["A perda de consistência visual (character drift) ocorre com mais frequência quando os prompts introduzem variações de figurino entre as cenas ou quando a trajetória da câmera ultrapassa rotações de 90 graus. Modelos generativos se fixam em texturas de tecidos e blocos de cor mais rapidamente do que na geometria facial sutil. Quando você troca a jaqueta de um personagem entre cortes, o modelo frequentemente reinterpreta a idade facial e a estrutura óssea para combinar com o novo estilo de roupa.", "Como detalhado no [guia de consistência da CawCut](https://www.cawcut.com/help/featured-tutorials/character-consistency-guide), separar as referências de rosto das referências de figurino e evitar oclusões extremas impede a maioria dos erros de continuidade. Além disso, análises artísticas no [estudo sobre folhas de personagens de Rutger Tuit](https://rutgertuit.nl/creative/character-sheet) ressaltam que testar o personagem em três planos básicos rápidos — plano aberto, plano médio e close-up — detecta desvios de identidade antes de iniciar a renderização completa da cena.", "A tabela a seguir apresenta os estados de erro mais comuns no DramaCanvas e como solucioná-los:", "| Mensagem de Erro ou Problema | Por Que Acontece | Como Resolver | |---|---|---| | Os traços faciais se deformam durante giros de câmera | O modelo não tem dados visuais laterais ou traseiros para aquele ângulo específico | Conecte um cartão de perfil ou de três quartos da sua folha-mestre ao nó de Vídeo antes de gerar. | | O figurino muda de cor ou estilo entre os cortes | O prompt de texto omitiu a descrição específica da peça de roupa | Insira novamente a descrição exata do figurino no prompt da cena; não dependa apenas da imagem de referência. | | Dois personagens se fundem em um único rosto | Os nomes e as referências de ambos os atores foram enviados sem separação clara de papéis | Descreva os atores por atributos visuais (\"o homem com jaqueta verde-oliva\" e \"a mulher com casaco cinza\") em vez de usar nomes próprios. | | \"Character voice generation accepts one character card at a time\" | Dois cartões de personagem foram conectados a um único nó de Áudio simultaneamente | Desconecte os cartões sobressalentes, mantendo apenas o personagem principal conectado ao nó de Áudio. | | \"This character has no usable voice bound, so a voice task cannot be created\" | O cartão de personagem conectado não possui um perfil de voz atribuído nos ativos do projeto | Abra o painel Project assets, vincule um perfil de voz ao cartão do personagem e reconecte o cabo ao nó de Áudio. | | \"This image model supports up to 16 reference images.\" | Os cabos de imagem conectados excedem a capacidade do modelo de imagem em uso | Desconecte os cabos de referência em excesso para ajustar as entradas ao limite do modelo. | | \"A reference image exceeds this model's file size limit.\" | O arquivo de referência enviado ultrapassa o teto máximo de 30 MB | Comprima o arquivo de imagem de origem antes de soltá-lo no canvas e reconecte os cabos de envio. | | \"Generated, but saving is incomplete\" | A renderização em nuvem foi concluída, mas oscilações na rede local atrasaram o salvamento da mídia | Não clique em gerar novamente; aguarde pelo menos um minuto inteiro e verifique se o cartão exibe \"Reload resource\". |", "Quando a movimentação de câmera exige uma marcação cênica complexa que ultrapassa o controle de prompts convencionais, você pode contornar os limites normais de texto para vídeo. Abra o nó **Director desk** na barra inferior para posicionar atores virtuais em 3D, ajustar pontos de iluminação e definir trilhos de câmera antes de gerar a cena. Como alternativa, desenvolvedores podem automatizar gráficos de cena inteiros com múltiplos planos por meio do [[link:claude-video-generation-mcp|servidor MCP do DramaCanvas]], encadeando referências de personagens em centenas de cenas."], "blocks": [{"type": "paragraph", "index": 0}, {"type": "paragraph", "index": 1}, {"type": "paragraph", "index": 2}, {"type": "table", "index": 3}, {"type": "paragraph", "index": 4}]}], "faq": [{"question": "É possível trocar o figurino de um personagem sem perder a identidade facial?", "answer": "Sim, mas você deve recortar seu cartão de referência bem próximo da cabeça e do pescoço do personagem para excluir a roupa anterior. Quando você conecta uma referência que mostra tanto o rosto quanto a jaqueta antiga, o modelo de vídeo prioriza o padrão daquela jaqueta. Ao isolar o rosto e descrever o novo figurino detalhadamente no prompt de texto, o modelo preserva a identidade facial enquanto renderiza as novas roupas."}, {"question": "Quantas imagens de referência você deve conectar a um nó de vídeo?", "answer": "Comece com 2 a 4 imagens de referência nítidas. Fornecer um retrato frontal, um ângulo em três quartos e uma silhueta de corpo inteiro cobre os principais ângulos. O Seedance 2.5 aceita até 30 imagens de referência; portanto, adicione mais ângulos ou figurinos apenas quando a cena realmente exigir."}, {"question": "Por que um nó de Áudio rejeitou uma imagem ou clipe de vídeo conectado?", "answer": "Os nós de Áudio aceitam estritamente prompts de texto ou exatamente um cartão de personagem com voz vinculada. Eles recusam arquivos de vídeo, imagens estáticas convencionais e conexões de áudio auxiliares na porta de entrada. Para gerar diálogos para um personagem, associe um perfil de voz ao cartão desse personagem dentro do painel Project assets antes de conectá-lo ao cartão de Áudio."}, {"question": "A conexão de cartões e a organização da folha de personagem consom créditos de geração?", "answer": "Nenhum crédito é consumido por operações de organização e layout. Adicionar cartões, movimentar nós pelo canvas infinito, recortar folhas de referência com o Grid split e arrastar cabos de conexão são ações totalmente gratuitas. Os créditos só são debitados quando você clica na seta de geração em um cartão individual, e o valor exato em créditos é exibido ao lado do botão antes do envio."}], "media": [], "cta": "/canvas", "closing": ["---", "Manter a continuidade de personagens em produções de vídeo com IA exige tratar a identidade visual como um ativo fixo, e não como um prompt temporário. Ao gerar uma folha-mestre de referência com o [[link:gpt-image-guide-2026|GPT Image 2]], salvar os ângulos recortados nos recursos do seu projeto e direcionar essas imagens para modelos multirreferência como o [[link:seedance-2-5|Seedance 2.5]] ou o [[link:kling-ai-guide-2026|Kling 4]], você garante que seu elenco permaneça reconhecível em cada transição de cena.", "Para começar a estruturar sua linha de produção, abra seu projeto no [canvas infinito do DramaCanvas](https://dramacanva.com), adicione um nó de Imagem para gerar sua folha-mestre de 4 ângulos e conecte as imagens aprovadas diretamente ao nó de Vídeo da sua primeira cena."], "howTo": false};
